matplotlib.rc('font', **font)

fig_size = [6,6]
plt.rcParams["figure.figsize"] = fig_size

plt.plot(range(1, len(loss_train)+1), loss_train, alpha=0.6, color= '#2D5AA9', linestyle='-.', label="Train Loss")    
plt.plot(range(1, len(loss_train)+1), loss_val, alpha=0.6, color='#FF8C00', linestyle='--', label="Val Loss")

w = 10
train_smooth = moving_average(loss_train, w)
val_smooth = moving_average(loss_val, w)
plt.plot(range(w, len(loss_train)+1), train_smooth, color='#1A3F8C', linewidth=2.4, label="Train Loss (smoothed)")
plt.plot(range(w, len(loss_val)+1), val_smooth, color='#D35400', linestyle='--', linewidth=2.4, label="Val Loss (smoothed)")
plt.legend(loc='upper right', fontsize=18)
plt.xlabel('Epoch', fontsize=18)
plt.ylabel('Loss', fontsize=18)
plt.tight_layout()
plt.savefig('loss.pdf', dpi=600)
